  -- 01. Caso clínico: EPOC grupo E con eosinófilos bajos y neumonía en LABA+CI
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"El corticoide que ya no se justifica","texto":"Un paciente con EPOC grupo E, eosinófilos bajos y dos neumonías sigue con LABA+ICS. El ICS no aporta beneficio y aumenta el riesgo. Retirarlo de forma planificada es una intervención de seguridad."},"objetivos":["Evaluar la indicación del ICS.","Aplicar el retiro planificado.","Revisar alternativas.","Prevenir exacerbaciones."],"conceptos":[{"icono":"TestTube","termino":"Eosinófilos","definicion":"Bajos si son menores de 100."},{"icono":"AlertTriangle","termino":"Neumonía","definicion":"Riesgo del ICS en EPOC."},{"icono":"Repeat","termino":"Retiro","definicion":"Planificado y supervisado."},{"icono":"Layers","termino":"LABA+LAMA","definicion":"Base del tratamiento."}],"secciones":[{"titulo":"Evaluación","parrafos":["El paciente tiene EPOC grupo E, eosinófilos bajos y neumonías recurrentes mientras recibe LABA+ICS. El ICS no está justificado si no hay exacerbaciones con eosinófilos elevados y el riesgo de neumonía es alto. Se revisan la historia, la espirometría, la técnica y la adherencia.","La decisión de retirar el ICS debe ser planificada y coordinada con el médico. Se mantiene LABA+LAMA y se refuerzan la vacunación y la rehabilitación."]},{"titulo":"Intervención","parrafos":["Se propone el retiro del ICS y el mantenimiento de LABA+LAMA. Si persisten las exacerbaciones, se valora roflumilast o azitromicina según el perfil. Se revisan los fármacos que pueden empeorar la EPOC y se educa sobre los signos de alarma.","El QF documenta la intervención y el plan de seguimiento. La comunicación con el equipo es clave."]},{"titulo":"Seguimiento","parrafos":["Se controlan las exacerbaciones, los síntomas, la técnica y la adherencia. La respuesta se evalúa en los meses siguientes. La vacunación y la rehabilitación pulmonar son parte del plan.","El caso muestra que la revisión de la indicación del ICS es una intervención de seguridad y de uso racional. La documentación de la decisión y de la evolución permite evaluar el impacto. La vacunación y la rehabilitación pulmonar se refuerzan en cada control. La revisión de la técnica y de la adherencia completa el plan. La comunicación con el equipo y el registro de las exacerbaciones facilitan los ajustes futuros."]}],"errores":[{"error":"Mantener ICS sin indicación.","correccion":"Riesgo de neumonía."},{"error":"Retirar sin plan.","correccion":"Debe ser supervisado."},{"error":"No revisar la técnica.","correccion":"Afecta el control."}],"comprueba":[{"pregunta":"¿Cuándo se justifica el ICS?","respuesta":"Con exacerbaciones y eosinófilos altos."},{"pregunta":"¿Qué riesgo tiene el ICS?","respuesta":"Neumonía."},{"pregunta":"¿Qué se mantiene al retirarlo?","respuesta":"LABA+LAMA."}],"resumen":["El ICS no es para todos los pacientes con EPOC.","Los eosinófilos bajos y las neumonías orientan el retiro.","El retiro es planificado.","La prevención sigue siendo clave."],"referencias":[{"cita":"Global Initiative for Chronic Obstructive Lung Disease. GOLD 2026 Pocket Guide. GOLD; 2025.","url":"https://goldcopd.org/2026-gold-report/"}],"imagenes":[{"ubicacion":"Caso","descripcion":"Revisión del ICS en EPOC grupo E.","alt":"Caso de EPOC con neumonía por ICS"}],"keywords":["epoc grupo e","retiro ics","neumonía","eosinófilos"],"mapa":{"centro":"EPOC grupo E","ramas":[{"titulo":"Riesgo","icono":"AlertTriangle","nodos":["Neumonía","Eos bajos","Exacerbaciones"]},{"titulo":"Decisión","icono":"Repeat","nodos":["Retirar ICS","Mantener LABA+LAMA"]},{"titulo":"Alternativa","icono":"Pill","nodos":["Roflumilast","Azitromicina","Rehabilitación"]},{"titulo":"Seguimiento","icono":"CalendarClock","nodos":["Exacerbaciones","Síntomas","Técnica"]}]},"proceso":{"titulo":"Revisar el ICS","intro":"","pasos":[{"titulo":"Indicación","detalle":"Exacerbaciones y eos.","icono":"TestTube","evidencia":"Laboratorio."},{"titulo":"Riesgo","detalle":"Neumonía y beneficio.","icono":"AlertTriangle","evidencia":"Historia."},{"titulo":"Retirar","detalle":"Planificado.","icono":"Repeat","evidencia":"Nota."},{"titulo":"Alternativa","detalle":"Roflumilast o macrólido.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Seguir","detalle":"Exacerbaciones y técnica.","icono":"CalendarClock","evidencia":"Control."}]},"caso":{"titulo":"Neumonías y eos bajos","contexto":"Paciente con EPOC grupo E, eosinófilos de 80 y dos neumonías en LABA+ICS.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Mantener el ICS.","correcta":false,"retro":"No hay beneficio y hay riesgo."},{"texto":"Proponer retirar el ICS y mantener LABA+LAMA.","correcta":true,"retro":"Reduce el riesgo de neumonía."},{"texto":"Duplicar el ICS.","correcta":false,"retro":"Empeora."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Caso clínico: EPOC grupo E con eosinófilos bajos y neumonía en LABA+CI$t$ AND deleted_at IS NULL
