  -- 02. Introducción a la unidad: depósito pulmonar y por qué el dispositivo importa
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"El fármaco que se queda en la boca","texto":"Un inhalador puede depositar la mayor parte del fármaco en la boca y no en el pulmón. El tamaño de partícula, el dispositivo y la técnica determinan el depósito pulmonar. Elegir bien es parte del tratamiento."},"objetivos":["Explicar el depósito pulmonar.","Reconocer el papel del dispositivo.","Aplicar criterios de selección.","Conectar técnica y eficacia."],"conceptos":[{"icono":"Droplets","termino":"Partícula","definicion":"Tamaño que permite llegar al pulmón."},{"icono":"Package","termino":"Dispositivo","definicion":"Determina el depósito."},{"icono":"Wind","termino":"Flujo","definicion":"Necesario para el polvo seco."},{"icono":"Eye","termino":"Técnica","definicion":"Los errores críticos anulan el efecto."}],"secciones":[{"titulo":"Depósito","parrafos":["El depósito pulmonar depende del tamaño de las partículas, la velocidad de la inhalación y la geometría de la vía aérea. Las partículas muy grandes se quedan en la boca y la garganta; las muy pequeñas pueden exhalarse. El dispositivo y la técnica modifican la fracción que llega al pulmón.","La vía inhalada busca maximizar el efecto local y minimizar los efectos sistémicos. Un inhalador mal usado equivale a un tratamiento que no llega."]},{"titulo":"Dispositivos","parrafos":["El inhalador presurizado requiere coordinación o cámara; el polvo seco requiere flujo inspiratorio suficiente; el inhalador de niebla fina genera una nube lenta que se inhala con calma; el nebulizador se usa en crisis o cuando no hay otra opción.","La elección depende de la edad, la capacidad inspiratoria, la destreza manual, la cognición y la cobertura. El dispositivo debe ser usable por el paciente."]},{"titulo":"Evaluación","parrafos":["El QF evalúa la técnica con una lista de verificación y detecta errores críticos. La demostración y la práctica son más eficaces que la explicación verbal. La revisión se repite en cada control y después de un cambio de dispositivo.","La educación incluye la limpieza, la conservación y el uso correcto. La técnica es parte del tratamiento. El teach-back y la observación directa detectan errores que la entrevista no revela. La revisión después de un cambio de dispositivo es obligatoria. La documentación de la técnica permite comparar y mejorar."]}],"errores":[{"error":"Elegir por costo sin usabilidad.","correccion":"El paciente debe poder usarlo."},{"error":"No demostrar la técnica.","correccion":"La explicación no basta."},{"error":"No revisar en cada control.","correccion":"Los errores reaparecen."}],"comprueba":[{"pregunta":"¿Qué determina el depósito?","respuesta":"Partícula, dispositivo y técnica."},{"pregunta":"¿Qué requiere el polvo seco?","respuesta":"Flujo inspiratorio."},{"pregunta":"¿Qué es un error crítico?","respuesta":"Un paso que anula el efecto."}],"resumen":["El depósito pulmonar es clave.","El dispositivo debe adaptarse al paciente.","La técnica se demuestra y se verifica.","Los errores críticos anulan el tratamiento."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"}],"imagenes":[{"ubicacion":"Unidad 4","descripcion":"Depósito pulmonar y dispositivos.","alt":"Depósito pulmonar y dispositivos de inhalación"}],"keywords":["depósito pulmonar","dispositivos inhalación","técnica","errores críticos"],"mapa":{"centro":"Depósito pulmonar","ramas":[{"titulo":"Partícula","icono":"Droplets","nodos":["Tamaño","Velocidad","Higroscopia"]},{"titulo":"Dispositivo","icono":"Package","nodos":["pMDI","DPI","Nebulizador"]},{"titulo":"Paciente","icono":"Users","nodos":["Flujo","Coordinación","Destreza"]},{"titulo":"Técnica","icono":"Eye","nodos":["Exhalar","Inhalar","Contener"]}]},"proceso":{"titulo":"Seleccionar dispositivo","intro":"","pasos":[{"titulo":"Paciente","detalle":"Edad y destreza.","icono":"Users","evidencia":"Evaluación."},{"titulo":"Flujo","detalle":"Capacidad inspiratoria.","icono":"Wind","evidencia":"Prueba."},{"titulo":"Dispositivo","detalle":"Opciones disponibles.","icono":"Package","evidencia":"Revisión."},{"titulo":"Demostrar","detalle":"Técnica paso a paso.","icono":"Eye","evidencia":"Práctica."},{"titulo":"Verificar","detalle":"Uso en control.","icono":"ClipboardCheck","evidencia":"Seguimiento."}]},"caso":{"titulo":"Inhalador mal usado","contexto":"Paciente con dosis correcta de ICS y mal control por técnica incorrecta.","pregunta":"¿Qué prioriza el QF?","opciones":[{"texto":"Cambiar el fármaco.","correcta":false,"retro":"El problema es la técnica."},{"texto":"Corregir la técnica y verificar.","correcta":true,"retro":"Mejora el depósito."},{"texto":"Duplicar la dosis.","correcta":false,"retro":"No corrige la causa."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
   WHERE course_id = v_curso AND title = $t$Introducción a la unidad: depósito pulmonar y por qué el dispositivo importa$t$ AND deleted_at IS NULL
