  -- 03. Inhalador presurizado (pMDI) y cámaras espaciadoras con válvula (con boquilla y con mascarilla)
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La cámara que cambia el resultado","texto":"Un niño usa un inhalador presurizado sin cámara y la familia no coordina la inhalación. La cámara espaciadora mejora el depósito y reduce los efectos locales. La técnica correcta es parte del tratamiento."},"objetivos":["Aplicar la técnica del pMDI.","Usar correctamente la cámara.","Reconocer errores críticos.","Educar y limpiar."],"conceptos":[{"icono":"Package","termino":"pMDI","definicion":"Inhalador presurizado."},{"icono":"Layers","termino":"Cámara","definicion":"Facilita la coordinación."},{"icono":"Eye","termino":"Técnica","definicion":"Agitar, exhalar e inhalar."},{"icono":"Users","termino":"Niños","definicion":"Mascarilla y supervisión."}],"secciones":[{"titulo":"Técnica del pMDI","parrafos":["Se retira la tapa, se agita y se acopla la cámara. El paciente exhala, sella los labios y presiona una vez mientras inhala lento y profundo; luego contiene la respiración unos diez segundos. Con cámara se puede respirar varias veces después de la pulsación.","Se espera entre 30 y 60 segundos antes de la siguiente inhalación. Con corticoides se enjuaga la boca. La cámara se lava con agua y jabón suave y se deja secar al aire."]},{"titulo":"Cámaras y mascarillas","parrafos":["La cámara con boquilla es preferible en niños mayores y adultos. La mascarilla se usa en lactantes y niños pequeños que no pueden sellar la boquilla. La válvula permite la inhalación y evita la exhalación dentro de la cámara.","La limpieza y el reemplazo según el fabricante son importantes. Una cámara sucia o dañada reduce el depósito."]},{"titulo":"Errores y educación","parrafos":["Los errores críticos incluyen no agitar, no exhalar, no sellar, presionar varias veces seguidas y no contener la respiración. La demostración y la práctica corrigen la técnica. El teach-back confirma la comprensión.","El QF revisa la técnica en cada control. La educación incluye el uso, la limpieza y la conservación. El cebado, el contador de dosis y el reemplazo de la cámara según el fabricante son parte de la instrucción. Un dispositivo vacío o una cámara dañada explican muchos fracasos aparentes. La revisión de la fecha de vencimiento y del contador evita quedarse sin tratamiento. La revisión de la técnica debe hacerse con el dispositivo del paciente, no con uno de demostración."]}],"errores":[{"error":"No agitar el pMDI.","correccion":"La dosis varía."},{"error":"No usar cámara en niños.","correccion":"La coordinación falla."},{"error":"No limpiar la cámara.","correccion":"Reduce el depósito."}],"comprueba":[{"pregunta":"¿Cuándo se usa mascarilla?","respuesta":"En lactantes y niños pequeños."},{"pregunta":"¿Cuánto se contiene la respiración?","respuesta":"Unos diez segundos."},{"pregunta":"¿Cómo se limpia la cámara?","respuesta":"Agua y jabón, secar al aire."}],"resumen":["El pMDI requiere coordinación o cámara.","La cámara mejora el depósito.","La mascarilla se usa en niños pequeños.","La limpieza y la técnica son clave."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"}],"imagenes":[{"ubicacion":"Dispositivos","descripcion":"pMDI con cámara y mascarilla.","alt":"Inhalador presurizado y cámara espaciadora"}],"keywords":["pmdi","cámara espaciadora","técnica inhalatoria","niños"],"mapa":{"centro":"pMDI y cámara","ramas":[{"titulo":"pMDI","icono":"Package","nodos":["Agitar","Presionar","Inhalar"]},{"titulo":"Cámara","icono":"Layers","nodos":["Boquilla","Mascarilla","Válvula"]},{"titulo":"Técnica","icono":"Eye","nodos":["Exhalar","Sellar","Contener"]},{"titulo":"Cuidado","icono":"Droplets","nodos":["Lavar","Secar","Reemplazar"]}]},"proceso":{"titulo":"Enseñar pMDI","intro":"","pasos":[{"titulo":"Preparar","detalle":"Agitar y acoplar.","icono":"Package","evidencia":"Demostración."},{"titulo":"Exhalar","detalle":"Fuera del dispositivo.","icono":"Wind","evidencia":"Práctica."},{"titulo":"Inhalar","detalle":"Presionar y respirar.","icono":"Eye","evidencia":"Práctica."},{"titulo":"Contener","detalle":"Diez segundos.","icono":"Timer","evidencia":"Verificación."},{"titulo":"Limpiar","detalle":"Cámara y boquilla.","icono":"Droplets","evidencia":"Consejería."}]},"caso":{"titulo":"Niño sin cámara","contexto":"Niño de 6 años que usa pMDI sin cámara y presenta crisis frecuentes.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Cambiar el fármaco.","correcta":false,"retro":"El problema es la técnica."},{"texto":"Enseñar la técnica con cámara.","correcta":true,"retro":"Mejora el depósito."},{"texto":"Suspender el rescate.","correcta":false,"retro":"No es seguro."}]}}$j$::jsonb;
  SELECT id INTO v_clase FROM aula_lessons
