     WHERE b.id = o.id AND b.sort_order IS DISTINCT FROM o.pos;
  END IF;

  -- 04. Inhaladores de polvo seco (DPI), inhalador de niebla fina y nebulizadores
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"No todos los dispositivos son iguales","texto":"El polvo seco exige inhalar fuerte; la niebla fina se inhala lento; el nebulizador requiere equipo y tiempo. Elegir el dispositivo adecuado es tan importante como elegir la molécula."},"objetivos":["Diferenciar los dispositivos.","Aplicar los requisitos de cada uno.","Reconocer ventajas y limitaciones.","Educar sobre limpieza y conservación."],"conceptos":[{"icono":"Wind","termino":"DPI","definicion":"Polvo seco; requiere flujo."},{"icono":"Droplets","termino":"Niebla fina","definicion":"Inhalación lenta y profunda."},{"icono":"Package","termino":"Nebulizador","definicion":"Equipo para crisis o incapacidad."},{"icono":"Eye","termino":"Técnica","definicion":"Cada dispositivo tiene pasos."}],"secciones":[{"titulo":"Polvo seco","parrafos":["Los DPI liberan el fármaco cuando el paciente inhala fuerte y profundo. Requieren un flujo inspiratorio suficiente y no se usan con cámara. Ejemplos incluyen Turbuhaler, Diskus, Ellipta y Handihaler.","No se debe exhalar dentro del dispositivo porque la humedad altera el polvo. La dosis se carga antes de cada uso y se cierra después. Con corticoides se enjuaga la boca."]},{"titulo":"Niebla fina y nebulizadores","parrafos":["El inhalador de niebla fina genera una nube lenta que se inhala con calma. Requiere cebado y limpieza. Los nebulizadores se usan en crisis o cuando el paciente no puede usar un inhalador; requieren equipo, higiene y tiempo.","La elección depende de la capacidad del paciente y del contexto. La nebulización no es superior si el inhalador se usa correctamente."]},{"titulo":"Educación","parrafos":["Cada dispositivo tiene pasos específicos. El QF demuestra, pide al paciente que lo haga y corrige. La limpieza y la conservación evitan obstrucciones y contaminación.","La revisión de la técnica en cada control detecta errores. La educación debe adaptarse al dispositivo y al paciente. La evaluación del flujo inspiratorio y de la destreza manual orienta la elección. El contador de dosis y la carga correcta evitan dosis perdidas. La limpieza y el secado del nebulizador reducen el riesgo de infección. La educación debe incluir la limpieza de la boquilla y la conservación del dispositivo. La revisión de la técnica se repite en cada control. La fecha de vencimiento también se revisa."]}],"errores":[{"error":"Usar cámara con DPI.","correccion":"No está indicada."},{"error":"No verificar el flujo.","correccion":"El fármaco no llega."},{"error":"No limpiar el nebulizador.","correccion":"Riesgo de infección."}],"comprueba":[{"pregunta":"¿Qué requiere el DPI?","respuesta":"Inhalación fuerte y profunda."},{"pregunta":"¿Cómo se inhala la niebla fina?","respuesta":"Lento y profundo."},{"pregunta":"¿Cuándo se usa nebulizador?","respuesta":"En crisis o incapacidad para inhalar."}],"resumen":["Cada dispositivo tiene requisitos.","El DPI exige flujo suficiente.","La niebla fina se inhala lento.","La limpieza y la técnica importan."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"}],"imagenes":[{"ubicacion":"Dispositivos","descripcion":"DPI, niebla fina y nebulizador.","alt":"Inhaladores de polvo seco y nebulizadores"}],"keywords":["dpi","polvo seco","respimat","nebulizador"],"mapa":{"centro":"Otros dispositivos","ramas":[{"titulo":"DPI","icono":"Wind","nodos":["Turbuhaler","Diskus","Ellipta"]},{"titulo":"Niebla","icono":"Droplets","nodos":["Respimat","Lenta","Cebado"]},{"titulo":"Nebulizador","icono":"Package","nodos":["Jet","Malla","Higiene"]},{"titulo":"Selección","icono":"Users","nodos":["Flujo","Destreza","Costo"]}]},"proceso":{"titulo":"Elegir y enseñar","intro":"","pasos":[{"titulo":"Evaluar","detalle":"Flujo y destreza.","icono":"Users","evidencia":"Prueba."},{"titulo":"Elegir","detalle":"DPI, niebla o nebulizador.","icono":"Package","evidencia":"Decisión."},{"titulo":"Demostrar","detalle":"Técnica específica.","icono":"Eye","evidencia":"Práctica."},{"titulo":"Limpiar","detalle":"Según fabricante.","icono":"Droplets","evidencia":"Consejería."},{"titulo":"Verificar","detalle":"Uso en control.","icono":"ClipboardCheck","evidencia":"Seguimiento."}]},"caso":{"titulo":"Artrosis y polvo seco","contexto":"Paciente mayor con artrosis que no logra activar el DPI.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Insistir en el mismo dispositivo.","correcta":false,"retro":"No es usable."},{"texto":"Buscar un dispositivo alternativo.","correcta":true,"retro":"La usabilidad es parte de la indicación."},{"texto":"Suspender el tratamiento.","correcta":false,"retro":"Necesita mantenimiento."}]}}$j$::jsonb;
