  -- 05. Rol del QF: evaluación de la técnica, adherencia, educación y farmacovigilancia
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La consulta de inhalación","texto":"Una consulta breve puede corregir errores críticos y mejorar el control. El QF evalúa la técnica, la adherencia y los efectos adversos. La educación y la farmacovigilancia cierran el ciclo."},"objetivos":["Evaluar la técnica.","Medir la adherencia.","Aplicar educación efectiva.","Reportar eventos adversos."],"conceptos":[{"icono":"Eye","termino":"Técnica","definicion":"Lista de verificación."},{"icono":"Calculator","termino":"Adherencia","definicion":"Dispensación y uso."},{"icono":"GraduationCap","termino":"Educación","definicion":"Demostración y teach-back."},{"icono":"FileCheck","termino":"Farmacovigilancia","definicion":"Reporte de sospechas."}],"secciones":[{"titulo":"Técnica y adherencia","parrafos":["La evaluación de la técnica usa una lista de verificación y detecta errores críticos. La adherencia se mide con registros de dispensación, cuestionarios o contadores. Las barreras incluyen olvido, costo, creencias y complejidad.","La intervención combina demostración, simplificación y recordatorios. La educación se adapta al paciente y a la familia."]},{"titulo":"Educación","parrafos":["El teach-back confirma la comprensión. El plan escrito y las metas pequeñas facilitan la adherencia. La educación debe incluir el propósito de cada inhalador, los efectos adversos y los signos de alarma.","La revisión en cada contacto refuerza la técnica y detecta cambios. La documentación permite evaluar la respuesta."]},{"titulo":"Farmacovigilancia","parrafos":["El QF detecta y reporta reacciones adversas, fallos terapéuticos y problemas de calidad. La sospecha no requiere certeza. El reporte incluye el fármaco, el lote, las fechas y el desenlace.","La farmacovigilancia se integra con la educación y el seguimiento. La comunicación con el equipo es parte del proceso. Los indicadores de la consulta de inhalación incluyen técnica correcta, adherencia, uso de rescate y exacerbaciones. La documentación de la intervención permite demostrar el impacto y sostener el programa. La revisión periódica de los casos detecta oportunidades de mejora. El reporte al INVIMA se documenta y se comunica al equipo. La educación sobre los signos de alarma y el uso correcto completa la intervención. La revisión del caso y de los indicadores cierra el ciclo de mejora."]}],"errores":[{"error":"Explicar sin demostrar.","correccion":"La práctica es necesaria."},{"error":"No medir la adherencia.","correccion":"Se asume un uso que no es real."},{"error":"No reportar.","correccion":"La farmacovigilancia protege."}],"comprueba":[{"pregunta":"¿Qué es teach-back?","respuesta":"El paciente explica y demuestra."},{"pregunta":"¿Cómo se mide la adherencia?","respuesta":"Dispensación y cuestionarios."},{"pregunta":"¿Qué se reporta?","respuesta":"Sospechas de reacciones adversas."}],"resumen":["La técnica se evalúa y se corrige.","La adherencia se mide.","La educación usa teach-back.","La farmacovigilancia cierra el ciclo."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"},{"cita":"Bhattarai A, Shakya R, Bista D. Impact of pharmacist-led intervention on adherence to inhalers, inhalation technique, and disease control. Patient Prefer Adherence. 2024;18:1395-408.","url":"https://doi.org/10.2147/ppa.s460810"}],"imagenes":[{"ubicacion":"Atención farmacéutica","descripcion":"Evaluación de la técnica y educación.","alt":"Rol del QF en terapia inhalada"}],"keywords":["técnica inhalatoria","adherencia","atención farmacéutica","farmacovigilancia"],"mapa":{"centro":"Atención farmacéutica","ramas":[{"titulo":"Técnica","icono":"Eye","nodos":["Errores","Demostración","Corrección"]},{"titulo":"Adherencia","icono":"Calculator","nodos":["Dispensación","Barreras","Simplificación"]},{"titulo":"Educación","icono":"GraduationCap","nodos":["Teach-back","Plan","Familia"]},{"titulo":"Seguridad","icono":"FileCheck","nodos":["Reporte","Efectos","Seguimiento"]}]},"proceso":{"titulo":"Consulta de inhalación","intro":"","pasos":[{"titulo":"Observar","detalle":"Técnica del paciente.","icono":"Eye","evidencia":"Lista."},{"titulo":"Corregir","detalle":"Errores críticos.","icono":"Settings","evidencia":"Práctica."},{"titulo":"Medir","detalle":"Adherencia y barreras.","icono":"Calculator","evidencia":"Datos."},{"titulo":"Educar","detalle":"Plan y teach-back.","icono":"GraduationCap","evidencia":"Consejería."},{"titulo":"Reportar","detalle":"Sospechas al INVIMA.","icono":"FileCheck","evidencia":"Reporte."}]},"caso":{"titulo":"Error crítico","contexto":"Paciente con ICS que no exhala antes de inhalar y presiona dos veces.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Cambiar el fármaco.","correcta":false,"retro":"El error es de técnica."},{"texto":"Demostrar y corregir con teach-back.","correcta":true,"retro":"Mejora el depósito."},{"texto":"Aumentar la dosis.","correcta":false,"retro":"No corrige la causa."}]}}$j$::jsonb;
