  -- 06. Caso clínico: adulta mayor con EPOC, artrosis y errores críticos de inhalación
  v_data := $j${"v":1,"duracion":25,"gancho":{"titulo":"La mano que no puede","texto":"Una adulta mayor con EPOC y artrosis no puede activar su inhalador. La técnica falla y el control empeora. Cambiar el dispositivo y adaptar la educación puede mejorar el resultado."},"objetivos":["Detectar errores críticos.","Adaptar el dispositivo.","Aplicar educación individualizada.","Evaluar el resultado."],"conceptos":[{"icono":"Users","termino":"Artrosis","definicion":"Limita la destreza manual."},{"icono":"Package","termino":"Dispositivo","definicion":"Debe adaptarse al paciente."},{"icono":"Eye","termino":"Error","definicion":"Paso que anula el efecto."},{"icono":"CalendarClock","termino":"Seguimiento","definicion":"Verificación y ajuste."}],"secciones":[{"titulo":"Evaluación","parrafos":["La paciente tiene EPOC, artrosis y dificultad para activar el inhalador. Se observa la técnica y se detectan errores críticos: no puede presionar, no coordina y no contiene la respiración. La limitación funcional es una barrera para el tratamiento.","Se revisan la destreza, la visión, la cognición y el apoyo familiar. La técnica se evalúa con una lista de verificación."]},{"titulo":"Intervención","parrafos":["Se propone un dispositivo más fácil de usar o una cámara espaciadora que reduzca la necesidad de coordinación. Se enseña la técnica con demostración y práctica. Se involucra a la familia o al cuidador.","La educación se adapta a la paciente y se refuerza en cada contacto. La revisión de la técnica y de la adherencia es parte del seguimiento."]},{"titulo":"Seguimiento","parrafos":["Se evalúan la técnica, los síntomas, las exacerbaciones y la adherencia. La mejoría del control confirma la intervención. La revisión periódica detecta nuevos errores.","El caso muestra que la farmacología respiratoria incluye la evaluación funcional y la adaptación del dispositivo. El cuidador recibe instrucción y participa en la práctica. La revisión repetida de la técnica detecta nuevos errores. La documentación de la intervención facilita la continuidad. La comunicación con el equipo permite ajustar el tratamiento sin perder el control. La revisión de la técnica y de la adherencia se repite en cada control. La educación del cuidador y la adaptación del dispositivo sostienen el resultado. La revisión de la técnica y de la adherencia se repite en cada visita."]}],"errores":[{"error":"No evaluar la destreza.","correccion":"El dispositivo puede no ser usable."},{"error":"No involucrar al cuidador.","correccion":"La técnica falla."},{"error":"No revisar en el control.","correccion":"Los errores reaparecen."}],"comprueba":[{"pregunta":"¿Qué barreras evaluar?","respuesta":"Destreza, visión y cognición."},{"pregunta":"¿Qué solución se propone?","respuesta":"Otro dispositivo o cámara."},{"pregunta":"¿Qué se controla?","respuesta":"Técnica y síntomas."}],"resumen":["La limitación funcional afecta la técnica.","El dispositivo debe adaptarse.","La educación incluye al cuidador.","El seguimiento verifica la técnica."],"referencias":[{"cita":"Global Initiative for Chronic Obstructive Lung Disease. GOLD 2026 Pocket Guide. GOLD; 2025.","url":"https://goldcopd.org/2026-gold-report/"}],"imagenes":[{"ubicacion":"Caso","descripcion":"Adulta mayor con errores críticos de inhalación.","alt":"Caso de inhalación en adulta mayor"}],"keywords":["adulta mayor epoc","errores inhalación","artrosis","dispositivo"],"mapa":{"centro":"Adulta mayor","ramas":[{"titulo":"Barreras","icono":"Users","nodos":["Artrosis","Visión","Cognición"]},{"titulo":"Errores","icono":"Eye","nodos":["Activar","Sellar","Inhalar"]},{"titulo":"Solución","icono":"Package","nodos":["Cámara","Otro dispositivo","Ayuda"]},{"titulo":"Seguimiento","icono":"CalendarClock","nodos":["Técnica","Síntomas","Adherencia"]}]},"proceso":{"titulo":"Adaptar el tratamiento","intro":"","pasos":[{"titulo":"Observar","detalle":"Técnica y barreras.","icono":"Eye","evidencia":"Lista."},{"titulo":"Elegir","detalle":"Dispositivo usable.","icono":"Package","evidencia":"Decisión."},{"titulo":"Enseñar","detalle":"Demostración y práctica.","icono":"GraduationCap","evidencia":"Práctica."},{"titulo":"Apoyar","detalle":"Cuidador y familia.","icono":"Users","evidencia":"Consejería."},{"titulo":"Seguir","detalle":"Control y ajuste.","icono":"CalendarClock","evidencia":"Consulta."}]},"caso":{"titulo":"No puede activar","contexto":"Paciente con EPOC y artrosis que no logra activar el inhalador.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Insistir con el mismo dispositivo.","correcta":false,"retro":"No es usable."},{"texto":"Adaptar el dispositivo y educar.","correcta":true,"retro":"Mejora el depósito."},{"texto":"Suspender el tratamiento.","correcta":false,"retro":"Necesita mantenimiento."}]}}$j$::jsonb;
