  -- 07. Introducción a la unidad: autocuidado, especialidad y salud pública en farmacología respiratoria
  v_data := $j${"v":1,"duracion":15,"gancho":{"titulo":"Más allá del inhalador","texto":"El autocuidado, la vacunación, la cesación tabáquica y la rehabilitación son parte del tratamiento respiratorio. La farmacia puede liderar estas intervenciones de salud pública."},"objetivos":["Reconocer el autocuidado.","Aplicar la prevención.","Conectar la farmacia con la salud pública.","Educar al paciente."],"conceptos":[{"icono":"Users","termino":"Autocuidado","definicion":"Peso, síntomas y adherencia."},{"icono":"ShieldCheck","termino":"Vacunas","definicion":"Influenza, neumococo y VSR."},{"icono":"Flame","termino":"Cesación","definicion":"Intervención clave."},{"icono":"Activity","termino":"Rehabilitación","definicion":"Mejora la función."}],"secciones":[{"titulo":"Autocuidado","parrafos":["El autocuidado incluye la técnica inhalatoria, la adherencia, el reconocimiento de signos de alarma y el registro de síntomas. En asma, el plan de acción escrito es fundamental. En EPOC, el peso y la actividad física importan.","La educación debe ser práctica y adaptada al paciente. La familia y el cuidador participan."]},{"titulo":"Prevención","parrafos":["La vacunación contra influenza, neumococo, VSR y COVID según indicación reduce complicaciones. La cesación tabáquica es la intervención más costo-efectiva en la EPOC. La reducción de la exposición a biomasa y alérgenos también importa.","La rehabilitación pulmonar mejora la capacidad funcional y reduce hospitalizaciones. La farmacia puede facilitar el acceso y la adherencia."]},{"titulo":"Salud pública","parrafos":["Los programas de farmacia pueden medir técnica correcta, uso de ICS, vacunación y exacerbaciones. La coordinación con EPS, IPS y programas de riesgo respiratorio amplía el impacto.","La documentación y la comunicación con el equipo son parte del proceso. La farmacia se integra a la salud pública. Los indicadores incluyen técnica correcta, vacunación, uso de rescate y exacerbaciones. La coordinación con los programas de riesgo respiratorio amplía el alcance. La educación comunitaria y la detección de barreras de acceso son parte del trabajo. La revisión periódica de los indicadores permite ajustar las intervenciones. La documentación y la comunicación con el equipo sostienen el programa. La participación de la comunidad y de los cuidadores amplía el impacto."]}],"errores":[{"error":"No revisar vacunas.","correccion":"Se pierde prevención."},{"error":"No ofrecer cesación.","correccion":"Es clave en EPOC."},{"error":"No documentar.","correccion":"No se sostiene el programa."}],"comprueba":[{"pregunta":"¿Qué vacunas se revisan?","respuesta":"Influenza, neumococo y VSR."},{"pregunta":"¿Qué mejora la rehabilitación?","respuesta":"Capacidad funcional y hospitalizaciones."},{"pregunta":"¿Qué indicadores se miden?","respuesta":"Técnica, ICS y exacerbaciones."}],"resumen":["El autocuidado es parte del tratamiento.","La prevención reduce complicaciones.","La rehabilitación mejora la función.","La farmacia se integra a la salud pública."],"referencias":[{"cita":"Global Initiative for Chronic Obstructive Lung Disease. GOLD 2026 Pocket Guide. GOLD; 2025.","url":"https://goldcopd.org/2026-gold-report/"}],"imagenes":[{"ubicacion":"Unidad 5","descripcion":"Autocuidado y prevención respiratoria.","alt":"Autocuidado y salud pública respiratoria"}],"keywords":["autocuidado respiratorio","vacunación","cesación tabáquica","rehabilitación"],"mapa":{"centro":"Salud respiratoria","ramas":[{"titulo":"Autocuidado","icono":"Users","nodos":["Técnica","Peso","Alarma"]},{"titulo":"Prevención","icono":"ShieldCheck","nodos":["Vacunas","Tabaco","Ambiente"]},{"titulo":"Rehabilitación","icono":"Activity","nodos":["Ejercicio","Educación","Soporte"]},{"titulo":"Farmacia","icono":"Landmark","nodos":["Programas","Seguimiento","Indicadores"]}]},"proceso":{"titulo":"Plan de autocuidado","intro":"","pasos":[{"titulo":"Evaluar","detalle":"Conocimientos y barreras.","icono":"Users","evidencia":"Entrevista."},{"titulo":"Enseñar","detalle":"Técnica y alarma.","icono":"GraduationCap","evidencia":"Consejería."},{"titulo":"Prevenir","detalle":"Vacunas y tabaco.","icono":"ShieldCheck","evidencia":"Registro."},{"titulo":"Rehabilitar","detalle":"Ejercicio y soporte.","icono":"Activity","evidencia":"Plan."},{"titulo":"Seguir","detalle":"Indicadores y ajuste.","icono":"LineChart","evidencia":"Control."}]},"caso":{"titulo":"Sin vacunas","contexto":"Paciente con EPOC que no tiene vacuna de influenza ni de neumococo.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Solo dispensar el inhalador.","correcta":false,"retro":"Falta prevención."},{"texto":"Revisar y completar vacunas.","correcta":true,"retro":"Reduce exacerbaciones."},{"texto":"Suspender el tratamiento.","correcta":false,"retro":"No es seguro."}]}}$j$::jsonb;
