  -- 08. Antitusivos, mucolíticos y expectorantes: qué dice la evidencia
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La tos que no necesita jarabe","texto":"La tos es un reflejo protector. Los antitusivos y mucolíticos tienen evidencia limitada y no siempre están indicados. La revisión de la causa y la educación evitan tratamientos innecesarios."},"objetivos":["Reconocer las indicaciones.","Evaluar la evidencia.","Reconocer los riesgos.","Educar al paciente."],"conceptos":[{"icono":"Pill","termino":"Antitusivo","definicion":"Suprime el reflejo de la tos."},{"icono":"Droplets","termino":"Mucolítico","definicion":"Fluidifica las secreciones."},{"icono":"AlertTriangle","termino":"Riesgo","definicion":"Sedación y efectos adversos."},{"icono":"Users","termino":"Educación","definicion":"La tos es protectora."}],"secciones":[{"titulo":"Antitusivos","parrafos":["Los antitusivos se usan en la tos seca e irritativa que interfiere con el sueño o la calidad de vida. El dextrometorfano es de venta libre y puede causar somnolencia; la codeína es un opioide y no se recomienda en niños. La miel puede aliviar la tos en adultos y niños mayores de un año.","No se usan en la tos productiva ni en la EPOC sin valoración. La supresión de la tos puede retener secreciones."]},{"titulo":"Mucolíticos y expectorantes","parrafos":["La acetilcisteína, el ambroxol y la guaifenesina se usan para fluidificar las secreciones. La evidencia es limitada y variable. Pueden causar molestias digestivas y reacciones alérgicas. En la EPOC, los mucolíticos tienen un papel limitado.","La hidratación y la humidificación del aire pueden ayudar. La revisión de la causa de la tos es más importante que el jarabe."]},{"titulo":"Educación","parrafos":["El paciente debe saber que la tos es un mecanismo de defensa y que no siempre requiere tratamiento. La persistencia, la fiebre, la disnea o la hemoptisis requieren consulta. La automedicación con combinados puede ser riesgosa.","El QF revisa la medicación y las interacciones. La educación y la derivación oportuna son parte del manejo. La revisión de los productos combinados evita duplicidades y sobredosis. En niños, se evitan los antitusivos y la codeína. La tos crónica requiere evaluación de la causa y no solo tratamiento sintomático. La revisión de la evidencia y de las preferencias del paciente permite decidir con criterio. La derivación oportuna y el seguimiento evitan complicaciones."]}],"errores":[{"error":"Suprimir la tos productiva.","correccion":"Retiene secreciones."},{"error":"Usar codeína en niños.","correccion":"Riesgo respiratorio."},{"error":"No revisar la causa.","correccion":"Se pierde un diagnóstico."}],"comprueba":[{"pregunta":"¿Cuándo se usa un antitusivo?","respuesta":"En tos seca que interfiere."},{"pregunta":"¿Qué evidencia tienen los mucolíticos?","respuesta":"Limitada."},{"pregunta":"¿Qué signos requieren consulta?","respuesta":"Fiebre, disnea o hemoptisis."}],"resumen":["La tos es un reflejo protector.","La evidencia de los jarabes es limitada.","La causa es lo primero.","La educación evita la automedicación."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"Tos","descripcion":"Antitusivos, mucolíticos y evidencia.","alt":"Antitusivos y mucolíticos"}],"keywords":["antitusivos","mucolíticos","tos","dextrometorfano"],"mapa":{"centro":"Tos","ramas":[{"titulo":"Antitusivos","icono":"Pill","nodos":["Dextrometorfano","Codeína","Miel"]},{"titulo":"Mucolíticos","icono":"Droplets","nodos":["NAC","Ambroxol","Guaifenesina"]},{"titulo":"Evidencia","icono":"LineChart","nodos":["Limitada","Sintomática","Causa"]},{"titulo":"Seguridad","icono":"AlertTriangle","nodos":["Sedación","Niños","Interacción"]}]},"proceso":{"titulo":"Evaluar la tos","intro":"","pasos":[{"titulo":"Tipo","detalle":"Seca o productiva.","icono":"Search","evidencia":"Entrevista."},{"titulo":"Causa","detalle":"Infección, reflujo o asma.","icono":"ClipboardList","evidencia":"Evaluación."},{"titulo":"Indicación","detalle":"Sintomático o específico.","icono":"Target","evidencia":"Decisión."},{"titulo":"Riesgo","detalle":"Sedación y edad.","icono":"AlertTriangle","evidencia":"Revisión."},{"titulo":"Educar","detalle":"Signos de alarma.","icono":"Users","evidencia":"Consejería."}]},"caso":{"titulo":"Tos productiva","contexto":"Paciente con tos productiva que solicita un antitusivo.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Dispensar el antitusivo.","correcta":false,"retro":"Puede retener secreciones."},{"texto":"Explicar y valorar la causa.","correcta":true,"retro":"La tos productiva no se suprime."},{"texto":"Duplicar la dosis.","correcta":false,"retro":"Riesgo innecesario."}]}}$j$::jsonb;
