  -- 09. Rinitis alérgica: antihistamínicos H1, corticoides intranasales, antileucotrienos y técnica del spray nasal
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"La rinitis que descontrola el asma","texto":"Una paciente con rinitis alérgica no tratada tiene más síntomas de asma. El control de la rinitis mejora la calidad de vida y el control respiratorio. La técnica del spray nasal también importa."},"objetivos":["Aplicar el tratamiento de la rinitis.","Diferenciar los fármacos.","Enseñar la técnica nasal.","Reconocer la relación con el asma."],"conceptos":[{"icono":"Wind","termino":"Rinitis","definicion":"Inflamación nasal alérgica."},{"icono":"ShieldCheck","termino":"Corticoide nasal","definicion":"Primera línea."},{"icono":"Pill","termino":"Antihistamínico","definicion":"Segunda generación."},{"icono":"Eye","termino":"Técnica","definicion":"Dirección y limpieza."}],"secciones":[{"titulo":"Tratamiento","parrafos":["Los corticoides intranasales son la primera línea para la rinitis alérgica moderada a grave. Los antihistamínicos de segunda generación, como cetirizina o loratadina, alivian los síntomas y causan menos sedación que los de primera generación. El montelukast es una opción en pacientes seleccionados.","Los descongestionantes se usan por pocos días por el riesgo de rinitis medicamentosa. El lavado nasal con solución salina es un complemento útil."]},{"titulo":"Técnica nasal","parrafos":["El paciente debe sonarse, inclinar la cabeza y dirigir el spray hacia la pared lateral de la nariz, no hacia el tabique. Se evita aspirar fuerte. La limpieza de la boquilla y el uso correcto mejoran la eficacia y reducen el sangrado.","La educación sobre la técnica es parte de la dispensación. La revisión en el control detecta errores."]},{"titulo":"Relación con el asma","parrafos":["La rinitis y el asma comparten la inflamación tipo 2. El tratamiento de la rinitis puede mejorar el control del asma. La revisión de la vía aérea superior es parte del manejo integral.","El QF revisa la adherencia, la técnica y los efectos adversos. La educación y el seguimiento son clave. El lavado nasal con solución salina es un complemento útil y seguro. En el embarazo se prefieren las opciones con mejor perfil de seguridad y se coordina con el equipo. La revisión de la técnica del spray y de la adherencia mejora el control."]}],"errores":[{"error":"Usar descongestionante por tiempo prolongado.","correccion":"Rinitis medicamentosa."},{"error":"No enseñar la técnica del spray.","correccion":"El fármaco no llega."},{"error":"Ignorar la relación con el asma.","correccion":"El control empeora."}],"comprueba":[{"pregunta":"¿Cuál es la primera línea?","respuesta":"El corticoide intranasal."},{"pregunta":"¿Qué antihistamínico se prefiere?","respuesta":"Los de segunda generación."},{"pregunta":"¿Cómo se dirige el spray?","respuesta":"Hacia la pared lateral."}],"resumen":["La rinitis alérgica se trata con corticoide nasal.","Los antihistamínicos de segunda generación son útiles.","La técnica nasal importa.","La rinitis afecta el control del asma."],"referencias":[{"cita":"Global Initiative for Asthma. GINA 2026 Summary Guide. GINA; 2026.","url":"https://ginasthma.org/2026-gina-strategy-report/"}],"imagenes":[{"ubicacion":"Rinitis","descripcion":"Tratamiento y técnica del spray nasal.","alt":"Rinitis alérgica y tratamiento"}],"keywords":["rinitis alérgica","corticoide intranasal","antihistamínicos","spray nasal"],"mapa":{"centro":"Rinitis alérgica","ramas":[{"titulo":"Corticoide","icono":"ShieldCheck","nodos":["Intranasal","Primera línea","Técnica"]},{"titulo":"Antihistamínico","icono":"Pill","nodos":["Cetirizina","Loratadina","Sedación"]},{"titulo":"Otros","icono":"Layers","nodos":["Montelukast","Descongestionante","Salino"]},{"titulo":"Asma","icono":"Wind","nodos":["Control","Técnica","Adherencia"]}]},"proceso":{"titulo":"Tratar la rinitis","intro":"","pasos":[{"titulo":"Evaluar","detalle":"Síntomas y gravedad.","icono":"ClipboardList","evidencia":"Entrevista."},{"titulo":"Elegir","detalle":"Corticoide o antihistamínico.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Técnica","detalle":"Dirección y limpieza.","icono":"Eye","evidencia":"Demostración."},{"titulo":"Revisar","detalle":"Asma y adherencia.","icono":"Wind","evidencia":"Control."},{"titulo":"Seguir","detalle":"Síntomas y efectos.","icono":"CalendarClock","evidencia":"Consulta."}]},"caso":{"titulo":"Rinitis y asma","contexto":"Paciente con rinitis alérgica y asma que no controla los síntomas nasales.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Ignorar la rinitis.","correcta":false,"retro":"Afecta el control del asma."},{"texto":"Tratar la rinitis y revisar la técnica.","correcta":true,"retro":"Mejora el control global."},{"texto":"Duplicar el broncodilatador.","correcta":false,"retro":"No trata la rinitis."}]}}$j$::jsonb;
