  -- 10. Fibrosis pulmonar idiopática: pirfenidona y nintedanib
  v_data := $j${"v":1,"duracion":20,"gancho":{"titulo":"Frenar la fibrosis","texto":"La fibrosis pulmonar idiopática es progresiva. La pirfenidona y el nintedanib enlentecen la pérdida de función pulmonar. La seguridad y el seguimiento son parte del tratamiento."},"objetivos":["Explicar el mecanismo.","Aplicar la dosis y la titulación.","Reconocer los efectos adversos.","Educar y monitorizar."],"conceptos":[{"icono":"Activity","termino":"Fibrosis","definicion":"Cicatrización progresiva del pulmón."},{"icono":"Pill","termino":"Pirfenidona","definicion":"Antifibrótico oral."},{"icono":"ShieldCheck","termino":"Nintedanib","definicion":"Inhibidor de tirosina cinasa."},{"icono":"AlertTriangle","termino":"Seguridad","definicion":"Digestivo y hepático."}],"secciones":[{"titulo":"Fármacos","parrafos":["La pirfenidona y el nintedanib enlentecen la disminución de la capacidad vital forzada en la fibrosis pulmonar idiopática. La pirfenidona se titula gradualmente y puede causar náuseas, diarrea, fotosensibilidad y elevación de transaminasas. El nintedanib puede causar diarrea, elevación de enzimas hepáticas y eventos hemorrágicos.","La elección depende de la tolerancia, las comorbilidades y el acceso. Ambos requieren control hepático y seguimiento de la función pulmonar."]},{"titulo":"Seguridad","parrafos":["La pirfenidona requiere protección solar y control de transaminasas. El nintedanib requiere vigilancia de la diarrea y del riesgo de sangrado, especialmente en pacientes anticoagulados. La adherencia es clave para el beneficio.","El QF revisa la medicación, las interacciones y los efectos adversos. La educación sobre la fotosensibilidad y la diarrea mejora la tolerancia."]},{"titulo":"Soporte","parrafos":["La rehabilitación pulmonar, la oxigenoterapia y el manejo de comorbilidades son parte del cuidado. La vacunación y el apoyo nutricional también importan. El trasplante se considera en casos seleccionados.","El seguimiento incluye espirometría, difusión, síntomas y calidad de vida. La comunicación con el equipo es clave. El manejo de la diarrea y de la fotosensibilidad permite mantener la adherencia. La vacunación y el soporte nutricional son parte del cuidado. En fases avanzadas, el enfoque paliativo y el trasplante se consideran de forma individualizada. La revisión de la adherencia y de los efectos adversos se realiza en cada control."]}],"errores":[{"error":"No controlar el hígado.","correccion":"Hepatotoxicidad."},{"error":"No advertir la fotosensibilidad.","correccion":"Reacción cutánea."},{"error":"No educar sobre la diarrea.","correccion":"Abandono del tratamiento."}],"comprueba":[{"pregunta":"¿Qué hacen los antifibróticos?","respuesta":"Enlentecen la pérdida de función."},{"pregunta":"¿Qué efecto tiene la pirfenidona?","respuesta":"Fotosensibilidad."},{"pregunta":"¿Qué se monitoriza?","respuesta":"LFT y función pulmonar."}],"resumen":["La pirfenidona y el nintedanib enlentecen la FPI.","La seguridad digestiva y hepática importa.","La educación mejora la tolerancia.","El soporte integral es clave."],"referencias":[{"cita":"Katzung BG, Vanderah TW. Basic and Clinical Pharmacology. 15.ª ed. McGraw-Hill; 2021.","url":"https://accessmedicine.mhmedical.com/book.aspx?bookid=2988"}],"imagenes":[{"ubicacion":"Fibrosis","descripcion":"Pirfenidona y nintedanib.","alt":"Fibrosis pulmonar idiopática"}],"keywords":["fibrosis pulmonar idiopática","pirfenidona","nintedanib","antifibrótico"],"mapa":{"centro":"Fibrosis pulmonar","ramas":[{"titulo":"Pirfenidona","icono":"Pill","nodos":["Titulación","Fotosensibilidad","Hígado"]},{"titulo":"Nintedanib","icono":"ShieldCheck","nodos":["Diarrea","Hígado","Sangrado"]},{"titulo":"Seguimiento","icono":"TestTube","nodos":["PFT","LFT","Síntomas"]},{"titulo":"Soporte","icono":"Users","nodos":["Rehabilitación","Oxígeno","Trasplante"]}]},"proceso":{"titulo":"Iniciar antifibrótico","intro":"","pasos":[{"titulo":"Diagnóstico","detalle":"FPI confirmada.","icono":"Search","evidencia":"Clínica."},{"titulo":"Elegir","detalle":"Pirfenidona o nintedanib.","icono":"Pill","evidencia":"Fórmula."},{"titulo":"Titular","detalle":"Tolerancia.","icono":"LineChart","evidencia":"Esquema."},{"titulo":"Monitorizar","detalle":"LFT y síntomas.","icono":"TestTube","evidencia":"Laboratorio."},{"titulo":"Apoyar","detalle":"Rehabilitación y vacunas.","icono":"Users","evidencia":"Plan."}]},"caso":{"titulo":"Diarrea por nintedanib","contexto":"Paciente con fibrosis pulmonar que inicia nintedanib y presenta diarrea.","pregunta":"¿Qué hace el QF?","opciones":[{"texto":"Ignorar el síntoma.","correcta":false,"retro":"Afecta la adherencia."},{"texto":"Educar, hidratar y coordinar el manejo.","correcta":true,"retro":"Mejora la tolerancia."},{"texto":"Duplicar la dosis.","correcta":false,"retro":"Empeora."}]}}$j$::jsonb;
